/**
 * Display formatting for money, counts, byte sizes and enum labels.
 *
 * The humanizers here are the only place a domain enum turns into prose —
 * components render `humanizeStatus(issue.status)` rather than carrying their
 * own label maps, so a new status value shows up consistently everywhere.
 */
import { UNLIMITED } from "@/config/plan-limits";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import type { Role } from "@/types/member";

export function formatCents(cents: number, currency = "USD"): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    minimumFractionDigits: 2,
  }).format(cents / 100);
}

/** 1_234 → "1,234"; 12_400 → "12.4K"; 3_100_000 → "3.1M". */
export function formatCount(value: number): string {
  const abs = Math.abs(value);
  if (abs < 10_000) return new Intl.NumberFormat("en-US").format(value);
  if (abs < 1_000_000) return `${trimZero(value / 1_000)}K`;
  return `${trimZero(value / 1_000_000)}M`;
}

function trimZero(value: number): string {
  return value.toFixed(1).replace(/\.0$/, "");
}

const BYTE_UNITS = ["B", "KB", "MB", "GB", "TB"] as const;

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${Math.round(bytes)} B`;
  let value = bytes;
  let unit = 0;
  while (value >= 1024 && unit < BYTE_UNITS.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return `${trimZero(value)} ${BYTE_UNITS[unit]}`;
}

/** Renders a plan quota, including the `Infinity` "no limit" sentinel. */
export function formatLimit(limit: number): string {
  return limit === UNLIMITED || !Number.isFinite(limit)
    ? "Unlimited"
    : formatCount(limit);
}

const STATUS_LABELS: Readonly<Record<IssueStatus, string>> = {
  backlog: "Backlog",
  todo: "Todo",
  in_progress: "In progress",
  in_review: "In review",
  done: "Done",
  canceled: "Canceled",
};

const PRIORITY_LABELS: Readonly<Record<IssuePriority, string>> = {
  none: "No priority",
  low: "Low",
  medium: "Medium",
  high: "High",
  urgent: "Urgent",
};

const ROLE_LABELS: Readonly<Record<Role, string>> = {
  owner: "Owner",
  admin: "Admin",
  member: "Member",
  viewer: "Viewer",
};

export function humanizeStatus(status: IssueStatus): string {
  return STATUS_LABELS[status];
}

export function humanizePriority(priority: IssuePriority): string {
  return PRIORITY_LABELS[priority];
}

export function humanizeRole(role: Role): string {
  return ROLE_LABELS[role];
}

/** The short reference shown on cards and in links, e.g. "TF-142". */
export function issueKey(projectKey: string, issueNumber: number): string {
  return `${projectKey.toUpperCase()}-${issueNumber}`;
}

import { z } from "zod";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issueStatusSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

export const createIssueSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  title: z.string().min(3, "give the issue a title").max(200),
  description: z.string().max(20_000).nullable().default(null),
  status: issueStatusSchema.default("backlog"),
  priority: issuePrioritySchema.default("none"),
  assigneeId: userIdSchema.nullable().default(null),
  parentId: issueIdSchema.nullable().default(null),
  estimate: z.number().int().min(0).max(100).nullable().default(null),
  dueAt: isoTimestampSchema.nullable().default(null),
  labelIds: z.array(labelIdSchema).max(20).default([]),
});

export const updateIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  title: z.string().min(3).max(200).optional(),
  description: z.string().max(20_000).nullable().optional(),
  priority: issuePrioritySchema.optional(),
  estimate: z.number().int().min(0).max(100).nullable().optional(),
  dueAt: isoTimestampSchema.nullable().optional(),
  labelIds: z.array(labelIdSchema).max(20).optional(),
});

export const changeIssueStatusSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  status: issueStatusSchema,
});

export const assignIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  assigneeId: userIdSchema.nullable(),
});

export const archiveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
});

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: z.array(issueStatusSchema).optional(),
    priority: z.array(issuePrioritySchema).optional(),
    assigneeId: userIdSchema.nullable().optional(),
    authorId: userIdSchema.optional(),
    labelIds: z.array(labelIdSchema).optional(),
    query: z.string().max(200).optional(),
    dueBefore: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape);

/** Board drag-and-drop payload: move one issue into a column at an index. */
export const moveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  toStatus: issueStatusSchema,
  toIndex: z.number().int().min(0),
});

const _statusParity: IssueStatus = "in_review" satisfies z.infer<
  typeof issueStatusSchema
>;
const _priorityParity: IssuePriority = "urgent" satisfies z.infer<
  typeof issuePrioritySchema
>;
void _statusParity;
void _priorityParity;

export type CreateIssueInput = z.infer<typeof createIssueSchema>;
export type UpdateIssueInput = z.infer<typeof updateIssueSchema>;
export type ChangeIssueStatusInput = z.infer<typeof changeIssueStatusSchema>;
export type AssignIssueInput = z.infer<typeof assignIssueSchema>;
export type IssueFilterInput = z.infer<typeof issueFilterSchema>;
export type MoveIssueInput = z.infer<typeof moveIssueSchema>;

