342	/** `pnpm db:seed` runs this file directly; importing it must stay inert. */
343	if (process.argv[1]?.endsWith("seed.ts") === true) {
344	  const summary = await seedDatabase();
345	  process.stdout.write(`${JSON.stringify(summary, null, 2)}\n`);
346	}
